import { test, expect } from '@playwright/test'
import { loginAsDeveloperCompanyOnce } from '../fixtures/auth-helpers.js'
import {
  isSurveyChangePageResponse,
  openSurveyChangeViewByProject,
  assertSurveyChangeHouseTableHasRows
} from '../fixtures/presale-survey-change-helpers.js'

/**
 * bug6070 验证：测绘成果变更详情「涉及房屋」分页控件不得被右侧裁掉。
 * 只读用例：复用列表已有记录「查看」入口，不新增/修改数据。
 */
test.describe('bug6070 涉及房屋分页控件完整可见', () => {
  test.setTimeout(180000)

  test('分页容器右边界落在详情页可视区内', async ({ page }) => {
    await loginAsDeveloperCompanyOnce(page)

    // 先回到测绘变更列表页，再取列表第一行
    const listResponse = page.waitForResponse(isSurveyChangePageResponse, { timeout: 30000 })
    await page.evaluate(() => {
      window.location.hash = '#/ysxkxsba/surveyChange'
    })
    await listResponse
    const listBody = await (await listResponse).json()
    if (listBody.code !== 200) {
      test.skip(true, `page 接口不可用：${listBody.msg}`)
      return
    }

    const firstRow = page.locator('.el-table__body-wrapper tbody tr').first()
    await expect(firstRow).toBeVisible({ timeout: 20000 })

    const detailResponse = page.waitForResponse(
      (r) => r.url().includes('/presale/surveyChange/detail'),
      { timeout: 30000 }
    )
    const viewBtn = firstRow.getByRole('button', { name: '查看' })
    if (await viewBtn.isVisible().catch(() => false)) {
      await viewBtn.click()
    } else {
      await firstRow.locator('.el-link, a').first().click()
    }
    await detailResponse
    await expect(page.getByTestId('survey-change-detail')).toBeVisible({ timeout: 20000 })

    // 等待「涉及房屋」分页数据返回；无数据则跳过布局断言（本例数据应为 6 行）
    await assertSurveyChangeHouseTableHasRows(page)
    await page.getByTestId('survey-change-house-table').scrollIntoViewIfNeeded()

    const pagination = page.locator('.detail-container .collapse-container .pagination-container').first()
    await expect(pagination).toBeVisible({ timeout: 20000 })

    // 关键断言：分页容器右边界不得超出详情容器可视右边界（允许 1px 取整误差）
    const detailBox = await page.getByTestId('survey-change-detail').boundingBox()
    const pagBox = await pagination.boundingBox()
    expect(detailBox).toBeTruthy()
    expect(pagBox).toBeTruthy()
    expect(
      pagBox.x + pagBox.width,
      `分页右边界 ${Math.round(pagBox.x + pagBox.width)} 超出详情右边界 ${Math.round(detailBox.x + detailBox.width)}`
    ).toBeLessThanOrEqual(Math.ceil(detailBox.x + detailBox.width) + 1)

    // 分页内部控件（页大小选择、跳页输入）也应完整落在页面可视宽度内
    const viewport = page.viewportSize()
    for (const [name, sel] of [
      ['页大小选择', '.el-pagination__sizes'],
      ['跳页输入', '.el-pagination__jump']
    ]) {
      const loc = pagination.locator(sel)
      if (await loc.count()) {
        const box = await loc.first().boundingBox()
        if (box) {
          expect(box.x + box.width, `${name}被裁掉`).toBeLessThanOrEqual(viewport.width + 1)
        }
      }
    }

    // 证据截图
    await pagination.screenshot({ path: 'e2e/output/bug6070/pagination-fixed.png' }).catch(() => {})
    await page.screenshot({ path: 'e2e/output/bug6070/detail-fixed.png', fullPage: false }).catch(() => {})
  })
})

